/// <summary>
/// Normalize a verify failure signature for cross-attempt comparison by stripping
/// timestamps and paths that embed attempt numbers, so identical environmental
/// failures (e.g. "mocha: command not found") match even when the output contains
/// per-attempt metadata.
/// </summary>
private static string NormalizeVerifySignature(string reason)
{
    if (string.IsNullOrEmpty(reason)) return string.Empty;
    // Strip ISO-8601 timestamps.
    var normalized = Iso8601Timestamp().Replace(reason, "");
    // Strip paths containing attempt numbers (e.g. "stage11-attempt1.verify-output.txt").
    normalized = AttemptPath().Replace(normalized, "");
    // Collapse whitespace.
    normalized = WhitespaceCollapse().Replace(normalized, " ").Trim();
    return normalized;
}

